const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.on('line', (input) => {
  const n = parseInt(input);
  const dp = Array.from(Array(n+2), () => new Array(n+2).fill(0));

  for (let len = 2; len <= n-1; len++) {
    for (let i = 1; i + len <= n; i++) {
      let j = i + len;
      dp[i][j] = Infinity;
      for (let k = i+1; k < j; k++) {
        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + (i * k * j));
      }
    }
  }

  console.log(dp[1][n]);
  rl.close();
});
