  input: process.stdin,
  output: process.stdout
});

let n;

rl.on('line', (line) => {
  n = parseInt(line);
  rl.close();
});

rl.on('close', () => {
  const dp = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

  for (let len = 2; len <= n; len++) {
    for (let i = 1; i <= n - len + 1; i++) {
      const j = i + len - 1;
      if (len === 2) {
        dp[i][j] = 0;
      } else {
        dp[i][j] = Infinity;
        for (let k = i + 1; k < j; k++) {
          dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + i * k * j);
        }
      }
    }
  }

  console.log(dp[1][n]);
});
